{"kind":"tool","id":"H55xWB0muQc","toolName":"write_file","input":{"path":"scripts/.mcp-probe-candidates.mjs","instructions":"Bulk-check candidate MCP package names on npm/PyPI for the catalog repair","content":"// One-off: probe candidate package names on npm/PyPI for the MCP catalog repair.
const names = process.argv.slice(2);

async function npmCheck(name) {
  const enc = name.startsWith("@") ? name.split("/").map(encodeURIComponent).join("/") : encodeURIComponent(name);
  try {
    const res = await fetch(`https://registry.npmjs.org/${enc}`, { signal: AbortSignal.timeout(8000) });
    if (res.status === 404) return `${name}\t npm: MISSING`;
    if (!res.ok) return `${name}\t npm: HTTP ${res.status}`;
    const j = await res.json();
    const latest = j["dist-tags"]?.latest ?? "";
    if (!latest) return `${name}\t npm: DEAD (no dist-tags)`;
    const v = j.versions?.[latest] ?? null;
    const dep = v?.deprecated ? ` DEPRECATED: ${String(v.deprecated).slice(0, 90)}` : "";
    const pub = (j.time?.[latest] ?? "").slice(0, 10);
    return `${name}\t npm: OK ${latest} (${pub})${dep}`;
  } catch (e) {
    return `${name}\t npm: ERR ${e?.cause?.code || e?.message}`;
  }
}
async function pypiCheck(name) {
  try {
    const res = await fetch(`https://pypi.org/pypi/${encodeURIComponent(name)}/json`, { signal: AbortSignal.timeout(8000) });
    if (res.status === 404) return `${name}\t pypi: MISSING`;
    if (!res.ok) return `${name}\t pypi: HTTP ${res.status}`;
    const j = await res.json();
    return `${name}\t pypi: OK ${j?.info?.version ?? "?"}`;
  } catch (e) {
    return `${name}\t pypi: ERR ${e?.cause?.code || e?.message}`;
  }
}

const out = [];
for (let i = 0; i < names.length; i += 6) {
  const chunk = names.slice(i, i + 6);
  const res = await Promise.all(chunk.map((n) => (n.startsWith("pypi:") ? pypiCheck(n.slice(5)) : npmCheck(n))));
  out.push(...res);
}
console.log(out.join("\n"));
