{"kind":"tool","id":"H6FRL2C83AM","toolName":"write_file","input":{"path":"scripts/.mcp-meta-candidates.mjs","instructions":"Print npm metadata for candidate packages to verify legitimacy","content":"// One-off: print npm metadata for candidate packages (description, repo, maintainers).
const names = process.argv.slice(2);
async function meta(name) {
  const enc = name.startsWith("@") ? name.split("/").map(encodeURIComponent).join("/") : encodeURIComponent(name);
  try {
    const res = await fetch(`https://registry.npmjs.org/${enc}`, { signal: AbortSignal.timeout(8000) });
    if (!res.ok) return `${name}: HTTP ${res.status}`;
    const j = await res.json();
    const latest = j["dist-tags"]?.latest ?? "";
    const v = j.versions?.[latest] ?? {};
    const repo = j.repository?.url ?? v.repository?.url ?? "?";
    const desc = (j.description ?? v.description ?? "?").slice(0, 110);
    const dep = v.deprecated ? ` [DEPRECATED: ${String(v.deprecated).slice(0, 60)}]` : "";
    return `${name} @${latest}\n  desc: ${desc}\n  repo: ${repo}\n  maintainers: ${(j.maintainers ?? []).map((m) => m.name).join(",").slice(0, 80)}${dep}`;
  } catch (e) {
    return `${name}: ERR ${e?.cause?.code || e?.message}`;
  }
}
for (let i = 0; i < names.length; i += 4) {
  const res = await Promise.all(names.slice(i, i + 4).map(meta));
  console.log(res.join("\n"));
}
"}}


