{"kind":"tool","id":"H6atTnHsUPU","toolName":"write_file","input":{"path":"scripts/.mcp-search.mjs","instructions":"Search npm and inspect PyPI/npm metadata and README usage for MCP package candidates","content":"// One-off: npm registry search + PyPI metadata for MCP catalog repair.
const [mode, ...rest] = process.argv.slice(2);

if (mode === "search") {
  for (const q of rest) {
    try {
      const res = await fetch(`https://registry.npmjs.org/-/v1/search?text=${encodeURIComponent(q)}&size=6`, { signal: AbortSignal.timeout(8000) });
      const j = await res.json();
      console.log(`\n== npm search: ${q}`);
      for (const o of j.objects ?? []) {
        const p = o.package;
        console.log(`  ${p.name}@${p.version} — ${(p.description ?? "").slice(0, 80)}`);
      }
    } catch (e) {
      console.log(`== ${q}: ERR ${e?.cause?.code || e?.message}`);
    }
  }
} else if (mode === "pypi") {
  for (const name of rest) {
    try {
      const res = await fetch(`https://pypi.org/pypi/${encodeURIComponent(name)}/json`, { signal: AbortSignal.timeout(8000) });
      if (!res.ok) { console.log(`${name}: HTTP ${res.status}`); continue; }
      const j = await res.json();
      console.log(`${name} @${j.info.version} author=${j.info.author ?? j.info.maintainer ?? "?"} home=${(j.info.home_page ?? j.info.project_urls?.Homepage ?? j.info.project_urls?.Repository ?? "?").slice(0, 90)}`);
    } catch (e) {
      console.log(`${name}: ERR ${e?.cause?.code || e?.message}`);
    }
  }
} else if (mode === "readme") {
  for (const name of rest) {
    try {
      const res = await fetch(`https://registry.npmjs.org/${name.startsWith("@") ? name.split("/").map(encodeURIComponent).join("/") : encodeURIComponent(name)}`, { signal: AbortSignal.timeout(8000) });
      if (!res.ok) { console.log(`${name}: HTTP ${res.status}`); continue; }
      const j = await res.json();
      const latest = j["dist-tags"]?.latest;
      const readme = j.readme ?? "";
      // Extract env var names and bin/usage lines.
      const envs = [...new Set((readme.match(/\b[A-Z][A-Z0-9_]{4,}\b/g) ?? []).filter((s) => !/^(HTTP|HTTPS|JSON|NODE|NPM|UTF|ASCII|MCP|TODO|NOTE|TEST|BASE|README|LICENSE|CHANGELOG|PACKAGE|DEFAULT|EXAMPLE|FEATURE|INSTALL|VERSION|DESCRIPTION|ARGUMENTS|OPTIONS|REQUIRED|OPTIONAL|PROTOCOL|CONTENT|ACCEPT|BEARER|TOKEN_TYPE)$/.test(s)))].slice(0, 25);
      const usage = (readme.match(/.{0,120}(npx|uvx|pip install|pnpm add|npm install).{0,160}/g) ?? []).slice(0, 3);
      console.log(`\n== ${name} @${latest}\n  env-ish: ${envs.join(", ")}\n  usage: ${usage.map((u) => u.replace(/\s+/g, " ")).join(" | ")}`);
    } catch (e) {
      console.log(`${name}: ERR ${e?.cause?.code || e?.message}`);
    }
  }
}
